/// Updated shipping information for the card.
public struct IssuingCardUpdateShipping: StripeParams {
    /// The address that the card is shipped to.
    public var address: IssuingCardShippingAddress
    /// The name printed on the shipping label when shipping the card.
    public var name: String
    /// Address validation settings.
    public var addressValidation: IssuingCardUpdateShippingAddressValidation?
    /// The name of the business at the shipping address, used on the shipping label to ensure delivery when
    /// the card is shipped to a cardholder's workplace. Allowed characters: `A-Z`, `a-z`, `0-9`, ` `, `.`,
    /// `-`. All other characters are stripped or ASCII-normalized when printed.
    public var businessName: String?
    /// Customs information for the shipment.
    public var customs: IssuingCardUpdateShippingCustoms?
    /// Phone number of the recipient of the shipment.
    public var phoneNumber: String?
    /// Whether a signature is required for card delivery.
    public var requireSignature: Bool?
    /// Shipment service.
    public var service: IssuingCardUpdateShippingService?
    /// Packaging options.
    public var type: IssuingCardUpdateShippingType?

    public init(address: IssuingCardShippingAddress, name: String, addressValidation: IssuingCardUpdateShippingAddressValidation? = nil, businessName: String? = nil, customs: IssuingCardUpdateShippingCustoms? = nil, phoneNumber: String? = nil, requireSignature: Bool? = nil, service: IssuingCardUpdateShippingService? = nil, type: IssuingCardUpdateShippingType? = nil) {
        self.address = address
        self.name = name
        self.addressValidation = addressValidation
        self.businessName = businessName
        self.customs = customs
        self.phoneNumber = phoneNumber
        self.requireSignature = requireSignature
        self.service = service
        self.type = type
    }

    public enum CodingKeys: String, CodingKey {
        case address
        case addressValidation = "address_validation"
        case businessName = "business_name"
        case customs
        case name
        case phoneNumber = "phone_number"
        case requireSignature = "require_signature"
        case service
        case type
    }
}

